import unittest
from candidate import is_palindrome, make_palindrome

class TestPalindromeOperations(unittest.TestCase):
    def test_is_palindrome_empty_string(self):
        self.assertTrue(is_palindrome(''))

    def test_is_palindrome_single_character(self):
        self.assertTrue(is_palindrome('a'))

    def test_is_palindrome_palindromic_string(self):
        self.assertTrue(is_palindrome('madam'))

    def test_is_palindrome_non_palindromic_string(self):
        self.assertFalse(is_palindrome('hello'))

    def test_make_palindrome_empty_string(self):
        self.assertEqual(make_palindrome(''), '')

    def test_make_palindrome_single_character(self):
        self.assertEqual(make_palindrome('a'), 'a')

    def test_make_palindrome_palindromic_string(self):
        self.assertEqual(make_palindrome('madam'), 'madam')

    def test_make_palindrome_non_palindromic_string(self):
        self.assertEqual(make_palindrome('cat'), 'catac')

    def test_make_palindrome_long_string(self):
        self.assertEqual(make_palindrome('cata'), 'catac')

    def test_make_palindrome_none_input(self):
        with self.assertRaises(TypeError):
            make_palindrome(None)

    def test_is_palindrome_none_input(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

if __name__ == '__main__':
    unittest.main()
